+                                try {
+                                    return r.pullRequest(record.prId());
+                                } catch (RuntimeException e) {
+                                    log.log(Level.WARNING, "Failed to retrieve pull request " + record.prId() + " from "
+                                            + r.name() + " for issue " + issue.id() + "; will retry the issue", e);
